```javascript
function isPrime(n) {
    if (n <= 1) return false;
    for (let i = 2, sqrt = Math.sqrt(n); i <= sqrt; i++)
        if (n % i === 0) return false;
    return true;
}

function checkPrimes(arr) {
    for (const num of arr) {
        if (isPrime(num)) {
            console.log(`Found prime number: ${num}`);
            return; // exit loop as soon as we find a prime
        }
    }
}

